use vstd::prelude::*;

verus! {

fn append(v: &Vec<u64>, elem: u64) -> (out: Vec<u64>)
    requires
        v.len() <= 100,
    ensures
        out.len() == v.len() + 1,
        forall|i: int|
            0 <= i < v.len() ==> out[i] == v[i],
        out[v.len() as int] == elem,
{
    let mut out: Vec<u64> = Vec::new();

    let mut i: usize = 0;
    while i < v.len()
        invariant
            i <= v.len(),
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == v[j],
        decreases v.len() - i,
    {
        out.push(v[i]);
        i = i + 1;
    }

    out.push(elem);

    // After the loop, out.len() == v.len(); after push, out.len() == v.len() + 1.
    assert(out.len() == v.len() + 1);

    // Prefix property for the full original length follows from the loop invariant at i == v.len().
    assert(forall|j: int| 0 <= j < v.len() ==> out[j] == v[j]);

    // The last element is the appended element.
    assert(out[v.len() as int] == elem);

    out
}

} // verus!

